create or replace function pipeline.svc_qilt_apply_observations(p_rows jsonb) returns jsonb language plpgsql security definer set search_path to 'pipeline','catalogue','ref','public','extensions' as $function$ declare r jsonb; v_changed integer:=0; v_seen integer:=0; v_rc integer; begin if p_rows is null or jsonb_typeof(p_rows)<>'array' then raise exception 'p_rows must be a JSON array'; end if; if jsonb_array_length(p_rows)>5000 then raise exception 'bounded apply limit exceeded'; end if; for r in select value from jsonb_array_elements(p_rows) loop v_seen:=v_seen+1; if not exists(select 1 from catalogue.providers p join ref.countries c on c.id=p.country_id where p.id=(r->>'provider_id')::uuid and c.iso_alpha2='AU') then raise exception 'QILT observation provider is not canonical AU CRICOS provider'; end if; if not exists(select 1 from ref.outcome_surveys s where s.id=(r->>'survey_id')::uuid and s.source_family='QILT' and s.status='active') then raise exception 'QILT observation survey is invalid'; end if; if not exists(select 1 from pipeline.source_provider_mappings m where m.source_id=(r->>'source_id')::uuid and m.source_entity_key=r->>'source_institution_key' and m.provider_id=(r->>'provider_id')::uuid and m.status='verified') then raise exception 'QILT observation lacks verified source-to-CRICOS mapping'; end if; insert into catalogue.provider_outcomes(provider_id,survey_id,metric_id,external_study_area_id,study_level_id,audience,source_cohort_code,collection_year_from,collection_year_to,metric_value,response_count,confidence_low,confidence_high,national_benchmark,source_id,evidence_id,source_institution_key,source_study_area_code,source_metric_code,observed_at,status,metadata) values((r->>'provider_id')::uuid,(r->>'survey_id')::uuid,(r->>'metric_id')::uuid,nullif(r->>'external_study_area_id','')::uuid,nullif(r->>'study_level_id','')::uuid,coalesce(nullif(r->>'audience',''),'all'),coalesce(nullif(r->>'source_cohort_code',''),'ALL'),(r->>'collection_year_from')::smallint,(r->>'collection_year_to')::smallint,nullif(r->>'metric_value','')::numeric,nullif(r->>'response_count','')::integer,nullif(r->>'confidence_low','')::numeric,nullif(r->>'confidence_high','')::numeric,nullif(r->>'national_benchmark','')::numeric,(r->>'source_id')::uuid,nullif(r->>'evidence_id','')::uuid,r->>'source_institution_key',nullif(r->>'source_study_area_code',''),r->>'source_metric_code',coalesce(nullif(r->>'observed_at','')::timestamptz,now()),coalesce(nullif(r->>'status',''),'current'),coalesce(r->'metadata','{}'::jsonb)) on conflict(provider_id,survey_id,metric_id,(coalesce(external_study_area_id,'00000000-0000-0000-0000-000000000000'::uuid)),(coalesce(study_level_id,'00000000-0000-0000-0000-000000000000'::uuid)),audience,source_cohort_code,collection_year_from,collection_year_to,source_id) do update set metric_value=excluded.metric_value,response_count=excluded.response_count,confidence_low=excluded.confidence_low,confidence_high=excluded.confidence_high,national_benchmark=excluded.national_benchmark,evidence_id=excluded.evidence_id,source_institution_key=excluded.source_institution_key,source_study_area_code=excluded.source_study_area_code,source_metric_code=excluded.source_metric_code,observed_at=excluded.observed_at,status=excluded.status,metadata=excluded.metadata,updated_at=now() where (catalogue.provider_outcomes.metric_value,catalogue.provider_outcomes.response_count,catalogue.provider_outcomes.confidence_low,catalogue.provider_outcomes.confidence_high,catalogue.provider_outcomes.national_benchmark,catalogue.provider_outcomes.evidence_id,catalogue.provider_outcomes.source_institution_key,catalogue.provider_outcomes.source_study_area_code,catalogue.provider_outcomes.source_metric_code,catalogue.provider_outcomes.status,catalogue.provider_outcomes.metadata) is distinct from (excluded.metric_value,excluded.response_count,excluded.confidence_low,excluded.confidence_high,excluded.national_benchmark,excluded.evidence_id,excluded.source_institution_key,excluded.source_study_area_code,excluded.source_metric_code,excluded.status,excluded.metadata); get diagnostics v_rc=row_count; v_changed:=v_changed+v_rc; end loop; return jsonb_build_object('seen',v_seen,'changed',v_changed); end $function$; revoke all on function pipeline.svc_qilt_apply_observations(jsonb) from public,anon,authenticated; grant execute on function pipeline.svc_qilt_apply_observations(jsonb) to service_role; create or replace function public.svc_qilt_apply_observations(p_rows jsonb) returns jsonb language sql security definer set search_path to 'pipeline','public' as $function$ select pipeline.svc_qilt_apply_observations(p_rows); $function$; revoke all on function public.svc_qilt_apply_observations(jsonb) from public,anon,authenticated; grant execute on function public.svc_qilt_apply_observations(jsonb) to service_role;
